void main(){
    vec2 uv = gl_FragCoord.xy / iResolution.xy;
    vec2 px = 1.0 / iResolution.xy;
    vec2 res = iChannelResolution[0].xy;
    vec3 src;
    if (any(greaterThan(res, iResolution.xy))) {
        // Catmull-Rom over a 4:1 source. Every tap of the 2:1 kernel becomes a
        // cluster of bilinear reads on the half-pixel grid, so all sixteen
        // source pixels under an output pixel are counted. Centre carries the
        // full box, the outer clusters carry the negative lobes.
        vec3 c = texture2D(iChannel0, uv + vec2( 0.25,  0.25) * px).rgb
               + texture2D(iChannel0, uv + vec2(-0.25,  0.25) * px).rgb
               + texture2D(iChannel0, uv + vec2( 0.25, -0.25) * px).rgb
               + texture2D(iChannel0, uv + vec2(-0.25, -0.25) * px).rgb;
        vec3 e = texture2D(iChannel0, uv + vec2( 0.75,  0.25) * px).rgb
               + texture2D(iChannel0, uv + vec2( 0.75, -0.25) * px).rgb
               + texture2D(iChannel0, uv + vec2(-0.75,  0.25) * px).rgb
               + texture2D(iChannel0, uv + vec2(-0.75, -0.25) * px).rgb
               + texture2D(iChannel0, uv + vec2( 0.25,  0.75) * px).rgb
               + texture2D(iChannel0, uv + vec2(-0.25,  0.75) * px).rgb
               + texture2D(iChannel0, uv + vec2( 0.25, -0.75) * px).rgb
               + texture2D(iChannel0, uv + vec2(-0.25, -0.75) * px).rgb;
        vec3 k = texture2D(iChannel0, uv + vec2( 0.75,  0.75) * px).rgb
               + texture2D(iChannel0, uv + vec2(-0.75,  0.75) * px).rgb
               + texture2D(iChannel0, uv + vec2( 0.75, -0.75) * px).rgb
               + texture2D(iChannel0, uv + vec2(-0.75, -0.75) * px).rgb;
        src = c * (81.0 / 256.0) + e * (-9.0 / 256.0) + k * (1.0 / 256.0);
    } else {
        // At the output's size or below, each pixel takes the source pixel
        // under its centre.
        src = texture2D(iChannel0, (floor(uv * res) + 0.5) / res).rgb;
    }
    float t = clamp(dot(src, vec3(0.299, 0.587, 0.114)), 0.0, 1.0);
    float v = t * 15.0;
    // The phase counts from the top left, as a panel scans.
    vec2 dpx = floor(vec2(gl_FragCoord.x, iResolution.y - gl_FragCoord.y));
    // The phase per pixel comes from the blue-noise mask, tiled, so the lit
    // set does not slide as one rigid field the way a gradient-noise phase does.
    vec2 cell = floor(mod(dpx, bluenoise_size));
    vec2 mt = (vec2(cell.x, bluenoise_size.y - 1.0 - cell.y) + 0.5) / bluenoise_size;
    // On VC4 a pass whose last texture read sits outside an if can run on two
    // threads, whose switch loses the condition flags. The if keeps it on one.
    float ph = 0.0;
    if (gl_FragCoord.x >= 0.0) ph = floor(texture2D(bluenoise_tex, mt).r * 16.0);
    float r = mod(float(iFrame) + ph, 16.0);
    float K = floor(fract(v) * 16.0 + 0.5);
    float L = floor(v) + step(0.5, floor((r + 1.0) * K / 16.0) - floor(r * K / 16.0));
    // L/15 lands on an exact hardware level: 255*L/15 is 17L, and the panel
    // takes the high nibble, which is L again. No rounding drift.
    float g = clamp(L, 0.0, 15.0) / 15.0;
    gl_FragColor = vec4(g, g, g, 1.0);
}
